// DSL gerada a partir de "imp_fk_variantes" - reimportável via Modelagem via DSL de Texto.

tabela pais {
    id integer pk
    sigla char(2) unique
    nome text
}

tabela estado {
    id smallint pk
    pais_id integer -> pais.id
    sigla char(2) not null -> pais.sigla
    pai_id smallint -> estado.id
}

tabela cidade {
    estado_id smallint not null -> estado.id
    pais_id integer not null -> pais.id
    codigo integer not null
    nome text
    chave (estado_id, codigo)
}

tabela bairro {
    cidade_estado smallint -> cidade.estado_id
    cidade_codigo integer -> cidade.codigo
    nome text
}

tabela semchave {
    a integer
    b integer
}

tabela ref_semchave {
    x integer
    y integer
}

tabela ck {
    id int
    txt text
    LIKE outra
}

tabela ordem_alter {
    id integer pk unique -> pais.id
}
